<template><span class="ui-avatar" :class="`ui-avatar--${size}`" :title="name"><img v-if="src" :src="src" :alt="name"><span v-else>{{ initials }}</span><i v-if="status" :class="`is-${status}`" aria-hidden="true"/></span></template>
<script setup lang="ts">import{computed}from'vue';const props=withDefaults(defineProps<{name:string;src?:string;size?:'sm'|'md'|'lg';status?:'online'|'busy'|'offline'}>(),{size:'md'});const initials=computed(()=>props.name.trim().split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase());</script>
<style scoped>.ui-avatar{position:relative;display:inline-grid;place-items:center;border:1px solid var(--ui-border);border-radius:50%;color:var(--ui-text-muted);background:var(--ui-surface-muted);font-size:11px;font-weight:600;overflow:visible}.ui-avatar--sm{width:24px;height:24px}.ui-avatar--md{width:32px;height:32px}.ui-avatar--lg{width:40px;height:40px}.ui-avatar img{width:100%;height:100%;border-radius:inherit;object-fit:cover}.ui-avatar i{position:absolute;right:-1px;bottom:-1px;width:8px;height:8px;border:2px solid var(--ui-surface);border-radius:50%;background:var(--ui-text-soft)}.ui-avatar i.is-online{background:var(--ui-success)}.ui-avatar i.is-busy{background:var(--ui-danger)}</style>
